/* PMAC public portal — static, GitHub Pages-compatible, with secure Supabase integration. */
'use strict';
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => Array.from(root.querySelectorAll(selector));
const cfg = window.PMAC_CONFIG || {};
const isConfigured = Boolean(cfg.supabaseUrl && cfg.supabasePublishableKey);
const db = isConfigured && window.supabase ? window.supabase.createClient(cfg.supabaseUrl, cfg.supabasePublishableKey) : null;
const app = $('#main');
const safe = value => String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readDate = value => value ? new Date(value).toLocaleDateString('en-AU',{day:'numeric',month:'long',year:'numeric'}) : 'Date to be announced';
const statusName = status => ({active:'In progress',closed:'Closed',pending:'Pending',published:'Published',received:'Received',under_review:'Under review',accepted:'Accepted',rejected:'Declined'}[status] || String(status || 'Unspecified'));
const link = (href, label, extra='') => `<a class="${extra}" href="${href}">${label}</a>`;
let publicCases=[]; let publicMembers=[]; let activeCasesStatus='all'; let activeCasesQuery=''; let activeMembersQuery=''; let adminTab='cases';
const icons = {
  arrow:'↗', scale:'⚖', balance:'Ⅲ', file:'▤', people:'◎', globe:'◇', shield:'✧', document:'§', message:'⌁'
};
function toast(message){const n=$('#toast');n.textContent=message;n.hidden=false;window.clearTimeout(toast.timer);toast.timer=window.setTimeout(()=>n.hidden=true,4700)}
function pageHero(label,title,lead){return `<section class="page-hero"><div class="shell"><div class="breadcrumbs"><a href="#/">Home</a><span>/</span>${safe(label)}</div><div class="eyebrow">${safe(label)}</div><h1>${title}</h1><p>${lead}</p></div></section>`}
function asideLinks(section='Information'){return `<aside class="side-panel"><h4>${section}</h4><a href="#/about">About PMAC <span>↗</span></a><a href="#/governance">Governance <span>↗</span></a><a href="#/membership">Membership <span>↗</span></a><a href="#/resources">Official documents <span>↗</span></a><a href="#/contact">Contact <span>↗</span></a></aside>`}
function notConfiguredNotice(){return !db ? `<div class="backend-note"><strong>Online filing is not yet activated.</strong>The website is ready, but its dedicated private database must be connected before an application or case can be transmitted. No information entered here will be stored until setup is complete. See the deployment instructions included with the project.</div>` : ''}
function formSubmitLabel(text){return `<button type="submit" class="btn btn-primary" ${db?'':'disabled'}>${text} <span aria-hidden="true">↗</span></button>`}
const home = () => `
<section class="institutional-hero" aria-label="Introduction to the Court">
  <div class="hero-photo" aria-hidden="true"></div>
  <div class="shell institutional-hero-inner">
    <div class="home-hero-text">
      <span class="hero-kicker">PERMANENT MICRO-ARBITRATION COURT</span>
      <h1>A forum for the peaceful settlement of micronational disputes.</h1>
      <p>The PMAC is a proposed independent institution providing a framework for voluntary arbitration, mediation and impartial case administration.</p>
      <a href="#/about" class="hero-readmore">About the Court <span aria-hidden="true">→</span></a>
    </div>
    <aside class="hero-reference" aria-label="Cases and quick reference">
      <h2>Search cases</h2>
      <form id="home-search-form" class="hero-case-search" role="search"><label class="sr-only" for="home-case-query">Search published case register</label><input id="home-case-query" type="search" name="q" placeholder="Enter case keywords…" maxlength="100"><button type="submit" aria-label="Search cases"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.8"/><path d="m15.5 15.5 5.4 5.4"/></svg></button></form>
      <h3>Quick reference</h3>
      <ul class="hero-resources"><li><a href="#/resources">Founding Convention <span>›</span></a></li><li><a href="#/resources">Proposed Arbitration Rules <span>›</span></a></li><li><a href="#/services">Dispute Resolution Services <span>›</span></a></li><li><a href="#/submit-case">How to Submit a Case <span>›</span></a></li></ul>
    </aside>
  </div>
  <div class="hero-credit">Illustrative architectural image. PMAC has no announced physical seat.</div>
</section>
<div class="founding-alert"><div class="shell"><span class="alert-pill">FOUNDING PHASE</span><span>The Founding Convention is proposed and the Court is not yet accepting formal proceedings.</span><a href="#/news">Read announcement <span aria-hidden="true">→</span></a></div></div>
<section class="editorial-section news-cases-section"><div class="shell"><div class="editorial-head"><h2>News &amp; Cases</h2><a href="#/news">See all news <span aria-hidden="true">›</span></a></div><div class="news-cases-grid"><article class="news-spot"><span class="news-type">INSTITUTIONAL NEWS</span><time datetime="2026-11-04">4 November 2026</time><h3><a href="#/news">Proposed founding framework for the Permanent Micro-Arbitration Court</a></h3><p>A draft convention outlines the institutional framework, judicial independence and voluntary jurisdiction of the proposed Court.</p><a class="editorial-link" href="#/news">Read more →</a></article><article class="news-spot"><span class="news-type">MEMBERSHIP</span><time>Founding phase</time><h3><a href="#/join">Invitations open to prospective founding micronations</a></h3><p>Discover the proposed admission process and how participating micronations would help shape the new institution.</p><a class="editorial-link" href="#/join">Membership information →</a></article><article class="news-spot case-news"><span class="news-type">PUBLIC CASES</span><time>Public register</time><h3><a href="#/cases">Cases and proceedings</a></h3><div id="home-case-preview" class="homepage-cases"><p>No published proceedings have been entered in the public register.</p><a class="editorial-link" href="#/cases">View the case register →</a></div></article></div></div></section>
<section class="intro-section"><div class="shell intro-columns"><div class="intro-copy"><span class="micro-label">THE INSTITUTION</span><h2>Dispute resolution based on consent, independence and fair procedure.</h2><p>The Permanent Micro-Arbitration Court is designed to offer micronations a neutral route to resolve disagreements without coercion. Its authority would be based solely on the documented agreement of the parties.</p><a href="#/about" class="outlined-cta">Learn more about PMAC <span aria-hidden="true">→</span></a></div><div class="intro-quote"><span class="quote-heading">DRAFT FOUNDING CONVENTION · ARTICLE VI</span><blockquote>“Jurisdiction shall require the documented consent of all necessary parties.”</blockquote><a href="documents/founding-convention.md" download>Read the draft Convention <span>↗</span></a></div></div></section>
<section class="editorial-section services-section"><div class="shell"><div class="editorial-head"><h2>Dispute Resolution Services</h2><a href="#/services">See all services <span aria-hidden="true">›</span></a></div><div class="service-list-grid"><a href="#/services" class="service-editorial"><span>01</span><h3>Arbitration</h3><p>An impartial, structured process by which a tribunal may determine issues within the scope agreed by the parties.</p><b>Learn more →</b></a><a href="#/services" class="service-editorial"><span>02</span><h3>Mediation</h3><p>Confidential, facilitated discussions to assist parties in negotiating a mutually acceptable settlement.</p><b>Learn more →</b></a><a href="#/services" class="service-editorial"><span>03</span><h3>Conciliation &amp; Administration</h3><p>Neutral facilitation, arbitrator appointments, case intake and procedural assistance.</p><b>Learn more →</b></a></div></div></section>
<section class="institution-footer-cta"><div class="shell"><div><span>WORK WITH THE COURT</span><h2>Participate in the founding framework.</h2><p>Review the membership conditions or request information about submitting a dispute.</p></div><div class="institution-footer-actions"><a href="#/join" class="cta-light">Apply for membership →</a><a href="#/submit-case" class="cta-outline">Submit a case →</a></div></div></section>`;
const about = () => `${pageHero('About the Court','An institution built for peaceful settlement.','The Permanent Micro-Arbitration Court is a proposed independent body for consent-based dispute resolution within the micronational community.')}<section class="page-section"><div class="shell content-layout"><article class="prose"><p class="lead">The PMAC seeks to make micronational diplomacy more constructive by offering a structured, accessible and impartial process for resolving disagreements.</p><h2>Our mandate</h2><p>The proposed Court would administer arbitration, mediation and related voluntary dispute-resolution processes. Its authority would derive from the agreement of those involved, not from any claim to sovereign status or compulsory jurisdiction.</p><p>The Government of Greenwick has been proposed as the initiating founder. Institutional governance is deliberately designed so that no founding member can direct arbitral outcomes.</p><div class="fancy-quote">“No single micronation should be both the convenor of justice and the judge of its own dispute.”<small>PMAC · PRINCIPLE OF INSTITUTIONAL INDEPENDENCE</small></div><h2>Legal and practical limitations</h2><p>PMAC is a voluntary micronational initiative. It is not the Permanent Court of Arbitration in The Hague, is not affiliated with that organisation, and is not an internationally recognised court. Its awards and recommendations do not displace courts, law enforcement or legal obligations under applicable national law.</p><p>Before accepting real cases, the founding members must adopt the Convention, elect officers, approve procedural rules and establish a secure Registry.</p><h2>Four institutional principles</h2><ul><li><strong>Consent:</strong> parties agree to the process and scope of jurisdiction.</li><li><strong>Independence:</strong> arbitrators disclose conflicts and cannot sit in their own disputes.</li><li><strong>Fair process:</strong> parties receive notice, a chance to respond and reasoned outcomes.</li><li><strong>Confidentiality:</strong> submissions are not published without an appropriate basis.</li></ul></article>${asideLinks()}</div></section>`;
const services = () => `${pageHero('Dispute resolution','Services and procedural pathways.','Choose an appropriate framework for managing a dispute. Arbitration begins only after the necessary parties agree to proceed.')}<section class="page-section"><div class="shell"><div class="section-heading"><div><span class="eyebrow">Available frameworks · proposed</span><h2>Our dispute resolution services</h2></div></div><div class="services-stack"><div class="service-box"><span class="service-mark">01 /</span><h3>Arbitration</h3><p>Formal, independent determination of agreed issues by one or three arbitrators with a reasoned written outcome.</p></div><div class="service-box"><span class="service-mark">02 /</span><h3>Mediation</h3><p>Confidential, facilitated negotiation to seek mutually agreed terms without an imposed decision.</p></div><div class="service-box"><span class="service-mark">03 /</span><h3>Conciliation</h3><p>A neutral facilitator helps clarify the dispute and may propose possible settlement terms.</p></div><div class="service-box"><span class="service-mark">04 /</span><h3>Procedural administration</h3><p>Case intake, communication between parties, appointment coordination and secure recordkeeping.</p></div></div><div class="two-column" style="margin-top:65px"><div><span class="eyebrow">How proceedings work</span><h2>From request to resolution.</h2><p class="section-lead">A fair process starts with jurisdiction, transparency and equal opportunity to be heard.</p><a href="#/submit-case" class="btn btn-primary">Request case intake ↗</a></div><div class="steps"><div class="step"><h4>File a preliminary request</h4><p>Identify the parties, dispute and preferred process.</p></div><div class="step"><h4>Confirm consent and jurisdiction</h4><p>The Registry checks whether all necessary parties agree.</p></div><div class="step"><h4>Appoint a neutral</h4><p>Conflicts are disclosed and appointments confirmed.</p></div><div class="step"><h4>Receive submissions and hear parties</h4><p>Equal opportunity to present relevant evidence and arguments.</p></div><div class="step"><h4>Document the outcome</h4><p>A settlement or reasoned decision is issued, subject to the chosen rules.</p></div></div></div><div class="notice" style="margin-top:44px"><strong>Jurisdictional limitation:</strong> PMAC cannot settle real-world property rights, criminal complaints or legal sovereignty. Urgent safety matters must be directed to competent authorities.</div></div></section>`;
const governance = () => `${pageHero('Governance','An independent institutional framework.','Separation between administration and adjudication is essential to public confidence in the Court.')}<section class="page-section"><div class="shell content-layout"><article class="prose"><p class="lead">The proposed Constitution establishes a Member Assembly, Administrative Council, Secretariat, Registry and case-specific arbitral tribunals.</p><div class="services-stack" style="margin:34px 0"><div class="service-box"><span class="service-mark">I</span><h3>Member Assembly</h3><p>One representative and one vote per admitted member. Approves rules and elects officers.</p></div><div class="service-box"><span class="service-mark">II</span><h3>Administrative Council</h3><p>Five elected members responsible for the integrity and administration of PMAC.</p></div><div class="service-box"><span class="service-mark">III</span><h3>Secretariat & Registry</h3><p>Maintains records, manages case intake and supports hearings.</p></div><div class="service-box"><span class="service-mark">IV</span><h3>Arbitral tribunals</h3><p>One or three impartial decision-makers selected under published appointment rules.</p></div></div><h2>Appointments and vacancies</h2><p>The organisation remains in its proposed founding phase. No elected president, council members or named arbitrators are represented on this website as appointed until publicly confirmed by a constituted Founding Assembly.</p><h2>Safeguards against interference</h2><ul><li>Declaration of conflicts of interest by decision-makers.</li><li>No administrative interference in the merits of a case.</li><li>Neutral challenge mechanism for disputed appointments.</li><li>Written decisions subject to limited procedural review.</li><li>Publication of institutional financial reporting.</li></ul><div class="notice"><strong>Important:</strong> the names and powers of officers become official only through adoption of the Convention and decisions of the founding membership.</div></article>${asideLinks('Institutional documents')}</div></section>`;
const membership = () => `${pageHero('Membership','Participation in the Court.','Member micronations may help shape an independent forum for the peaceful settlement of disputes.')}<section class="page-section"><div class="shell content-layout"><article class="prose"><h2>Membership principles</h2><p class="lead">A participating micronation accepts the Court's Founding Convention and supports impartial, voluntary dispute resolution.</p><p>Membership would provide representation in the Assembly, eligibility to nominate qualified candidates for institutional office, and access to relevant Court processes in accordance with approved procedural rules.</p><ul><li>One member micronation, one vote in the Assembly.</li><li>Equal institutional standing regardless of size or prominence.</li><li>No obligation to arbitrate a particular dispute merely because of membership.</li><li>No guarantee of recognition as a sovereign state.</li></ul><div class="notice"><strong>Founding membership:</strong> the proposed Convention enters into force after acceptance by at least three independent founding micronations. Applications can only be formally processed when the Secretariat and database are operational.</div><h2>Proposed admission process</h2><div class="steps"><div class="step"><h4>Apply</h4><p>Provide the micronation's name and an authorised representative.</p></div><div class="step"><h4>Registry review</h4><p>Verify the information and willingness to adopt the Convention.</p></div><div class="step"><h4>Institutional decision</h4><p>The competent founding or membership body determines admission.</p></div><div class="step"><h4>Public confirmation</h4><p>Approved membership appears in the public directory with permission.</p></div></div><a href="#/join" class="btn btn-primary" style="margin-top:19px">Start membership application ↗</a><h2>Public membership directory</h2><p>Search confirmed and publicly listed member micronations. Applications awaiting a decision are private and are not included in this register.</p><form id="member-search-form" class="member-directory-search" role="search"><label for="member-search">Search the member directory</label><div class="member-directory-controls"><input id="member-search" name="q" type="search" autocomplete="off" maxlength="120" placeholder="Enter a micronation name or website" value="${safe(activeMembersQuery)}"><button type="submit" class="btn btn-primary">Search members</button><button type="button" id="clear-member-search" class="btn btn-outline-light">Clear</button></div></form><p id="member-search-summary" class="search-result-summary" role="status" aria-live="polite"></p><div id="member-list"><div class="empty-state"><div class="symbol">◎</div><h3>Founding member register</h3><p>No members have yet been entered into the public directory. This section updates from the database when activated.</p></div></div></article>${asideLinks()}</div></section>`;
function casesPage(){return `${pageHero('Case registry','Public cases and proceedings.','Find authorised public records of arbitration, mediation and other proceedings before PMAC. Confidential filings will not appear here.')}<section class="page-section"><div class="shell"><div class="notice notice-dark" style="margin-top:0"><strong>Publication safeguards:</strong> a preliminary submission is private and does not become a public case automatically. The Registry must approve every published record.</div><div class="tab-bar" role="tablist" aria-label="Filter cases"><button class="tab ${activeCasesStatus==='all'?'active':''}" data-case-status="all">All cases</button><button class="tab ${activeCasesStatus==='active'?'active':''}" data-case-status="active">In progress</button><button class="tab ${activeCasesStatus==='closed'?'active':''}" data-case-status="closed">Closed</button><button class="tab ${activeCasesStatus==='pending'?'active':''}" data-case-status="pending">Pending</button></div><div class="searchbar"><input class="searchinput" type="search" id="case-search" aria-label="Search cases" placeholder="Search by case number, party or keyword" value="${safe(activeCasesQuery)}"><select id="case-category" aria-label="Case category"><option value="all">All categories</option><option value="diplomatic">Diplomatic</option><option value="treaty">Treaty interpretation</option><option value="constitutional">Constitutional</option><option value="electoral">Electoral</option><option value="organisational">Organisational</option><option value="territorial">Territorial claims</option><option value="other">Other</option></select><button type="button" id="clear-case-search" class="btn btn-outline-light">Clear filters</button></div><p id="case-search-summary" class="search-result-summary" role="status" aria-live="polite"></p><div id="case-results"><div class="empty-state"><div class="symbol">§</div><h3>Checking the public case register</h3><p>Public records are retrieved from the authorised database.</p></div></div><p style="font-size:.76rem;color:#8b979f;margin-top:17px">Case publication may be restricted by privacy, party consent and procedural orders.</p></div></section>`}
const cooperation=()=>`${pageHero('Global cooperation','Cooperation across the micronational community.','PMAC seeks constructive relations among voluntarily participating micronations and organisations, without asserting sovereign recognition or compulsory authority.')}<section class="page-section"><div class="shell content-layout"><article class="prose"><p class="lead">A forum for dialogue, procedural assistance and voluntary peaceful settlement.</p><h2>Participation and partnerships</h2><p>Micronations may express interest in the founding process, participate in consultations on procedural rules and—once the institution is properly constituted—apply for membership under the adopted Convention.</p><h2>Working with organisations</h2><p>Micronational associations and community organisations may request information about mediation, arbitration processes, case administration and educational cooperation. Such engagement does not constitute diplomatic recognition under international law.</p><h2>Principles of cooperation</h2><ul><li>Equal treatment of participating parties.</li><li>Independence of arbitral tribunals from member governments.</li><li>Recognition of applicable national laws and courts.</li><li>Transparency in appointments, governance and funding.</li><li>Private handling of sensitive preliminary proceedings.</li></ul><h2>Become involved</h2><p>Review the membership framework and submit an expression of interest on the Join PMAC page. An expression of interest is not itself an admission to the Court.</p><a href="#/join" class="btn btn-primary">Join the founding dialogue →</a></article>${asideLinks('Participation')}</div></section>`;
const resources=()=>`${pageHero('Documents & resources','Conventions, rules and guidance.','Public access to foundational documents, procedural guidance and information governing the proposed Court.')}<section class="page-section"><div class="shell content-layout"><article><span class="eyebrow">Constitutional instruments</span><h2 style="margin-top:16px">Founding documents</h2><div class="document-list">${[['Founding Convention — Draft 1.0','Proposed constitutional framework of the PMAC','documents/founding-convention.md'],['Rules of Procedure — Draft','Case intake, arbitrator appointment and hearings','documents/rules-of-procedure.md'],['Code of Ethics — Draft','Independence, recusal and impartiality','documents/code-of-ethics.md'],['Privacy & Data Handling Standard','Public and private case information','documents/privacy-standard.md']].map(([a,b,c])=>`<div class="document-row"><div class="document-left"><div class="document-icon">§</div><div><h3>${a}</h3><p>${b}</p></div></div><a href="${c}" download>Download ↗</a></div>`).join('')}</div><div class="notice"><strong>Document status:</strong> all constitutional and procedural instruments linked above are draft proposals, not ratified or legally operative rules.</div><h2 style="margin:55px 0 18px">Questions about proceedings</h2><details class="faq-item"><summary>Does PMAC have compulsory jurisdiction?</summary><p>No. Jurisdiction is established by documented consent of the parties concerned.</p></details><details class="faq-item"><summary>Will case documents be public?</summary><p>No. Filed information is private by default. Public case records require a separate approval step.</p></details><details class="faq-item"><summary>Can PMAC order law enforcement to act?</summary><p>No. PMAC cannot exercise state criminal jurisdiction or direct recognised authorities.</p></details><details class="faq-item"><summary>Is PMAC affiliated with the PCA?</summary><p>No. PMAC is an independent micronational initiative, not a branch or affiliate of the Permanent Court of Arbitration (PCA).</p></details></article>${asideLinks('Resource navigation')}</div></section>`;
const news=()=>`${pageHero('Notices & news','Institutional announcements.','Official public notices concerning the formation, procedures and future activity of PMAC.')}<section class="page-section"><div class="shell content-layout"><article><span class="eyebrow">Institutional notices</span><div class="news-card"><time datetime="2026-11-04">4 November 2026</time><div><h3>PMAC founding framework proposed</h3><p>A draft Founding Convention, governance model and voluntary case framework have been prepared for consideration by prospective founding micronations. The Court is not yet constituted.</p></div></div><div class="news-card"><time>Founding phase</time><div><h3>Call for prospective founding participants</h3><p>Micronations interested in impartial and consent-based dispute settlement are invited to review the proposed framework and membership requirements. Formal admission awaits constitution of the institution.</p></div></div></article>${asideLinks('Explore PMAC')}</div></section>`;
const contact=()=>`${pageHero('Contact & enquiries','Get in touch with the Registry.','The Secretariat is not yet formally appointed. Use the designated pathways to understand membership or case filing requirements.')}<section class="page-section"><div class="shell"><div class="services-stack"><a class="service-box" href="#/join"><span class="service-mark">01 /</span><h3>Membership enquiries ↗</h3><p>Review eligibility and prepare an application to join the Court.</p></a><a class="service-box" href="#/submit-case"><span class="service-mark">02 /</span><h3>Case intake ↗</h3><p>Review filing requirements and the information needed by the Registry.</p></a><a class="service-box" href="#/resources"><span class="service-mark">03 /</span><h3>Documents and rules ↗</h3><p>Read proposed institutional documents and procedural rules.</p></a><a class="service-box" href="#/governance"><span class="service-mark">04 /</span><h3>Governance enquiries ↗</h3><p>Understand the Court's formation and institutional independence.</p></a></div><div class="notice" style="margin-top:35px"><strong>No official postal address or contact email has been designated.</strong> Do not send confidential files or sensitive personal details through public GitHub issues or social media messages.</div></div></section>`;
const privacy=()=>`${pageHero('Privacy','Privacy and data handling.','How the proposed Court website is designed to handle membership applications and case requests.')}<section class="page-section"><div class="shell content-layout"><article class="prose"><h2>Information collected</h2><p>The membership form requests information about the applicant micronation and its authorised representative. The case form requests party identities, a contact address and a summary of the dispute.</p><h2>Purpose and access</h2><p>Information is used solely for membership administration, assessment of a voluntary case request and related Registry communication. Private filings should only be accessible to specifically approved Registry administrators through authenticated accounts and database row-level security.</p><h2>Public disclosure</h2><p>Submitting a case does not consent to public disclosure. Public case records are held in a separate database table and require an affirmative publication decision, with appropriate protection of personal data.</p><h2>Security and retention</h2><p>Database hosting and any third-party service details must be documented after operational setup. PMAC's officers must establish a defined retention schedule, access-log review and data deletion procedure before accepting sensitive submissions. Do not include identity documents, passwords or highly sensitive information in the initial forms.</p><h2>Your rights</h2><p>Applicants may seek correction or deletion through the designated Registry contact once published. Relevant local privacy law may apply regardless of PMAC's micronational status.</p><div class="notice">This is an initial website privacy statement. A legally reviewed privacy policy and a published contact point are required before the Court becomes operational.</div></article>${asideLinks('Public information')}</div></section>`;
function joinPage(){return `${pageHero('Join the Court','Apply for micronational membership.','Complete the preliminary application to register your micronation’s interest in participating in the proposed Court.')}<section class="page-section section-muted"><div class="shell form-layout"><form id="join-form" class="form-card"><span class="eyebrow">Membership application</span><h2 style="margin-top:17px">Information about your micronation</h2><p class="form-intro">Fields marked * are required. Your application remains private until separately approved for public listing.</p>${notConfiguredNotice()}<div class="field"><label for="member-name">Official micronation name <span class="required">*</span></label><input id="member-name" name="entity_name" required maxlength="130" placeholder="e.g. Commonwealth of…" autocomplete="organization"></div><div class="field-row"><div class="field"><label for="member-founded">Year established</label><input id="member-founded" name="founded_year" type="number" min="1800" max="2100" placeholder="2024"></div><div class="field"><label for="member-website">Official website</label><input id="member-website" name="website" type="url" maxlength="250" placeholder="https://example.org"></div></div><div class="field-row"><div class="field"><label for="member-rep">Authorised representative <span class="required">*</span></label><input id="member-rep" name="representative" required maxlength="130" autocomplete="name"></div><div class="field"><label for="member-title">Official title <span class="required">*</span></label><input id="member-title" name="representative_title" required maxlength="130" placeholder="Head of Government, Minister…"></div></div><div class="field"><label for="member-email">Official contact email <span class="required">*</span></label><input id="member-email" name="contact_email" type="email" required maxlength="250" autocomplete="email"></div><div class="field"><label for="member-region">Primary operating region</label><input id="member-region" name="region" maxlength="130" placeholder="Region or country (optional)"></div><div class="field"><label for="member-description">About your micronation <span class="required">*</span></label><textarea id="member-description" name="description" maxlength="2500" minlength="25" required placeholder="Briefly describe your micronation, government and interest in PMAC."></textarea><small class="hint">25–2,500 characters. Do not enter private identification details.</small></div><label class="check-field"><input type="checkbox" name="charter_acknowledged" required> <span>I have reviewed the proposed Founding Convention and understand that this is a voluntary institutional initiative, not a recognised state court. *</span></label><label class="check-field"><input type="checkbox" name="authority_confirmed" required> <span>I confirm I am authorised to submit this application on behalf of the named micronation. *</span></label><label class="check-field"><input type="checkbox" name="privacy_acknowledged" required> <span>I have read the <a href="#/privacy" style="text-decoration:underline">privacy notice</a> and agree to Registry use of this information for application review. *</span></label><div class="form-honey" aria-hidden="true"><label>Leave blank<input name="website_confirm" tabindex="-1" autocomplete="off"></label></div><div id="join-message" role="status"></div><div class="form-actions">${formSubmitLabel('Submit membership application')}<small>Submitting an application does not confer membership.</small></div></form><div><aside class="form-help"><span class="eyebrow">Before you apply</span><h3 style="margin-top:17px">Principles of membership</h3><p>Membership is open to qualifying micronational participants willing to uphold:</p><ul><li>Peaceful resolution of disputes</li><li>Equal institutional standing</li><li>Fair procedure and impartiality</li><li>Non-interference with national law</li></ul><a href="#/resources" class="btn btn-outline-light" style="margin-top:10px">Read founding documents ↗</a></aside><div class="side-small"><strong>What happens next?</strong><p>A Registrar, once appointed, will assess applications under the approved admission procedure. Approval is not automatic.</p></div></div></div></section>`}
function caseSubmitPage(){return `${pageHero('Case submission','Request arbitration or mediation.','Use this confidential intake form to present a proposed dispute. Filing does not establish the Court’s jurisdiction.')}<section class="page-section section-muted"><div class="shell form-layout"><form id="case-form" class="form-card"><span class="eyebrow">Private Registry request</span><h2 style="margin-top:17px">Preliminary case details</h2><p class="form-intro">Initial filings are private. Do not include passwords, identity documents, sensitive evidence or information about minors at this stage.</p>${notConfiguredNotice()}<div class="field"><label for="case-title">Short case title <span class="required">*</span></label><input id="case-title" name="title" required maxlength="180" placeholder="Dispute concerning…"></div><div class="field-row"><div class="field"><label for="case-type">Type of dispute <span class="required">*</span></label><select id="case-type" name="category" required><option value="">Select a category</option><option value="diplomatic">Diplomatic</option><option value="treaty">Treaty interpretation</option><option value="constitutional">Constitutional</option><option value="electoral">Electoral</option><option value="organisational">Organisational</option><option value="territorial">Territorial claims</option><option value="other">Other micronational dispute</option></select></div><div class="field"><label for="case-process">Preferred process <span class="required">*</span></label><select id="case-process" name="requested_process" required><option value="">Select a process</option><option value="mediation">Mediation</option><option value="arbitration">Arbitration</option><option value="conciliation">Conciliation</option><option value="unsure">Not yet decided</option></select></div></div><div class="field-row"><div class="field"><label for="case-claimant">Claimant / requesting party <span class="required">*</span></label><input id="case-claimant" name="claimant" required maxlength="180"></div><div class="field"><label for="case-respondent">Respondent / other party <span class="required">*</span></label><input id="case-respondent" name="respondent" required maxlength="180"></div></div><div class="field-row"><div class="field"><label for="case-filer">Name of representative <span class="required">*</span></label><input id="case-filer" name="filer_name" required maxlength="140" autocomplete="name"></div><div class="field"><label for="case-filer-role">Official capacity <span class="required">*</span></label><input id="case-filer-role" name="filer_role" required maxlength="140" placeholder="Your role"></div></div><div class="field"><label for="case-email">Contact email <span class="required">*</span></label><input id="case-email" type="email" name="contact_email" required maxlength="250" autocomplete="email"></div><div class="field"><label for="case-consent">Consent to PMAC proceedings <span class="required">*</span></label><select id="case-consent" name="consent_status" required><option value="">Select current status</option><option value="both">Both parties have agreed in principle</option><option value="claimant_only">Only the requesting party has agreed</option><option value="not_yet">Consent is not yet confirmed</option></select><span class="hint">The Registry must verify the necessary consent independently before arbitration.</span></div><div class="field"><label for="case-summary">Summary of the dispute <span class="required">*</span></label><textarea id="case-summary" name="summary" required minlength="50" maxlength="7000" placeholder="Explain the background, the central disagreement and any attempts to resolve it."></textarea><span class="hint">50–7,000 characters.</span></div><div class="field"><label for="case-relief">Outcome requested <span class="required">*</span></label><textarea id="case-relief" name="relief_requested" required minlength="15" maxlength="3000" placeholder="What determination, agreement or assistance are you seeking?"></textarea></div><label class="check-field"><input name="authority_confirmed" type="checkbox" required> <span>I am authorised to make this preliminary request for the requesting party. *</span></label><label class="check-field"><input name="accept_limitations" type="checkbox" required> <span>I understand this request creates no compulsory jurisdiction or real-world enforcement powers. *</span></label><label class="check-field"><input name="privacy_acknowledged" type="checkbox" required> <span>I understand the information is submitted privately to the Registry under the <a href="#/privacy" style="text-decoration:underline">privacy notice</a>. *</span></label><div class="form-honey" aria-hidden="true"><label>Leave blank<input name="website_confirm" tabindex="-1" autocomplete="off"></label></div><div id="case-message" role="status"></div><div class="form-actions">${formSubmitLabel('Send preliminary request')}<small>Receipt is not acceptance of jurisdiction or appointment of a tribunal.</small></div></form><div><aside class="form-help"><span class="eyebrow">Intake checklist</span><h3 style="margin-top:17px">What you should know</h3><ul><li>All necessary parties must consent before arbitration begins.</li><li>A preliminary request does not mean a case has been admitted.</li><li>Only approved public summaries appear in the case register.</li><li>Serious safety or criminal matters belong with real-world authorities.</li></ul><a href="#/services" class="btn btn-outline-light" style="margin-top:10px">Review case process ↗</a></aside><div class="side-small"><strong>Confidential filing</strong><p>There is no document upload in the initial portal. A secure evidence-exchange process must be introduced before private attachments are accepted.</p></div></div></div></section>`}
function adminPage(){return `${pageHero('Registry administration','Registry workspace.','Restricted access for officially appointed and authorised Registry administrators.')}<section class="page-section"><div class="shell" id="admin-root"><div class="form-card" style="max-width:550px"><h2>Authorised staff sign-in</h2><p>Enter the credentials of an authorised Registry account. Access is verified by database permissions, not by this page alone.</p>${notConfiguredNotice()}<form id="admin-login"><div class="field"><label for="admin-email">Email address</label><input id="admin-email" type="email" name="email" required autocomplete="username"></div><div class="field"><label for="admin-pass">Password</label><input id="admin-pass" type="password" name="password" required autocomplete="current-password"></div><div id="admin-login-message" role="status"></div><button class="btn btn-primary" ${db?'':'disabled'}>Sign in ↗</button></form></div></div></section>`}
function notFound(){return `<section class="not-found shell"><strong>404</strong><h2>Page not found</h2><p>The requested document or service could not be located.</p><a href="#/" class="btn btn-primary">Back to homepage ↗</a></section>`}
const routes={'/':home,'/about':about,'/services':services,'/cases':casesPage,'/membership':membership,'/governance':governance,'/cooperation':cooperation,'/resources':resources,'/news':news,'/contact':contact,'/privacy':privacy,'/join':joinPage,'/submit-case':caseSubmitPage,'/admin':adminPage};
function route(){const h=window.location.hash || '#/';return (h.startsWith('#/')?h.slice(1).split('?')[0]:'/').replace(/\/$/,'')||'/'}
async function render(){const path=route();const renderPage=routes[path]||notFound;app.innerHTML=renderPage();document.title=`${({ '/':'Home','/about':'About','/services':'Services','/cases':'Case register','/membership':'Membership','/join':'Join PMAC','/submit-case':'Submit a case','/governance':'Governance','/cooperation':'Global cooperation','/resources':'Documents','/news':'News','/contact':'Contact','/privacy':'Privacy','/admin':'Registry access'}[path]||'Not found')} | Permanent Micro-Arbitration Court`;
  $$('.desktop-nav a,.mobile-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+path));$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'auto'});
  if(path==='/cases') await loadCases();
  if(path==='/membership') await loadMembers();
  if(path==='/admin') await initAdmin();
  if(path==='/') await loadHomeCases();
}
async function queryPublicCases(){if(!db) return null;const {data,error}=await db.from('published_cases').select('case_number,title,category,claimant,respondent,status,summary,published_at').eq('is_public',true).order('published_at',{ascending:false}).limit(1000);if(error)throw error;return data||[]}
function renderPublicCases(){
 const el=$('#case-results'); if(!el)return;
 const summary=$('#case-search-summary');
 if(!db){
   if(summary)summary.textContent='The public case register is not connected to a database.';
   el.innerHTML='<div class="empty-state"><h3>Register unavailable</h3><p>The case database has not been connected. Please contact the Registry.</p></div>';
   return;
 }
 const category=$('#case-category')?.value||'all';
 const search=activeCasesQuery.toLocaleLowerCase().trim();
 const filtered=publicCases.filter(c=>(activeCasesStatus==='all'||c.status===activeCasesStatus)&&(category==='all'||c.category===category)&&[c.case_number,c.title,c.claimant,c.respondent,c.summary,c.category].some(v=>String(v||'').toLocaleLowerCase().includes(search)));
 if(summary)summary.textContent=publicCases.length? `${filtered.length} of ${publicCases.length} published case records displayed`:'0 published cases';
 if(!publicCases.length){
   el.innerHTML='<div class="empty-state"><div class="symbol">§</div><h3>No cases have been published</h3><p>The Registry may have received private submissions, but no case has yet been authorised for the public register. Public search cannot display confidential filings.</p></div>';
 } else if(!filtered.length){
   el.innerHTML='<div class="empty-state"><div class="symbol">§</div><h3>No matching public cases</h3><p>Try a different keyword or clear the filters. Only officially published case records are searchable.</p></div>';
 } else {
   el.innerHTML='<div class="registry-list">'+filtered.map(c=>`<article class="registry-entry"><div><small>${safe(c.case_number)} · ${safe(c.category)} · ${readDate(c.published_at)}</small><strong>${safe(c.title)}</strong><p>${safe(c.claimant)} v. ${safe(c.respondent)}${c.summary?' · '+safe(c.summary.slice(0,195)):''}</p></div><span class="status-tag ${safe(c.status)}">${safe(statusName(c.status))}</span></article>`).join('')+'</div>';
 }
}
async function loadCases(){const el=$('#case-results');try{const cases=await queryPublicCases();if(!$('#case-results'))return;publicCases=cases||[];renderPublicCases()}catch(e){console.error(e);if(el)el.innerHTML=`<div class="error-box">The public case register is temporarily unavailable. Please try again later.</div>`}}
function renderMembers(){
 const el=$('#member-list');if(!el)return;
 const summary=$('#member-search-summary');
 if(!db){
   if(summary) summary.textContent='The public member directory is unavailable.';
   el.innerHTML='<div class="empty-state"><h3>Directory unavailable</h3><p>The member directory has not been connected to a database.</p></div>';
   return;
 }
 const search=activeMembersQuery.trim().toLocaleLowerCase();
 const filtered=publicMembers.filter(m=>[m.name,m.website].some(x=>String(x||'').toLocaleLowerCase().includes(search)));
 if(summary)summary.textContent=publicMembers.length?`${filtered.length} of ${publicMembers.length} published members displayed`:'0 publicly listed members';
 if(!publicMembers.length){
   el.innerHTML='<div class="empty-state"><div class="symbol">◎</div><h3>No members have been published</h3><p>Submitted membership applications are private until formally approved and separately added to the public directory by an authorised Registry administrator.</p></div>';
 }else if(!filtered.length){
   el.innerHTML='<div class="empty-state"><div class="symbol">◎</div><h3>No matching members</h3><p>Try another name, or clear the member search.</p></div>';
 }else{
   el.innerHTML='<div class="document-list">'+filtered.map(m=>`<div class="document-row"><div><h3>${safe(m.name)}</h3><p>Admitted ${readDate(m.admitted_on)}</p></div>${m.website&&/^https:\/\//.test(m.website)?`<a href="${safe(m.website)}" target="_blank" rel="noopener noreferrer">Official site ↗</a>`:''}</div>`).join('')+'</div>';
 }
}
async function loadMembers(){
 if(!db){renderMembers();return}
 const el=$('#member-list');
 try{
   const {data,error}=await db.from('members').select('name,website,admitted_on').eq('is_public',true).eq('status','active').order('name').limit(1000);
   if(error)throw error;
   if(!$('#member-list'))return;
   publicMembers=data||[];
   renderMembers();
 }catch(e){
   console.error('Public member directory error',e);
   if(el)el.innerHTML='<div class="error-box">The public member directory could not be loaded. Please try again later.</div>';
   const summary=$('#member-search-summary');if(summary)summary.textContent='Unable to retrieve members.';
 }
}
async function loadHomeCases(){if(!db)return;try{const cases=await queryPublicCases();const el=$('#home-case-preview');if(!el||!cases?.length)return;el.innerHTML=`<div class="registry-list">${cases.slice(0,3).map(c=>`<article class="registry-entry"><div><small>${safe(c.case_number)} · ${readDate(c.published_at)}</small><strong>${safe(c.title)}</strong><p>${safe(c.claimant)} v. ${safe(c.respondent)}</p></div><span class="status-tag ${safe(c.status)}">${safe(statusName(c.status))}</span></article>`).join('')}</div>`}catch(e){console.warn('Could not load home cases',e)}}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function referenceCode(prefix){let bytes=new Uint8Array(6);if(window.crypto?.getRandomValues)window.crypto.getRandomValues(bytes);else bytes=Uint8Array.from({length:6},()=>Math.floor(Math.random()*256));return `PMAC-${prefix}-${new Date().getFullYear()}-${Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('').toUpperCase()}`}
function disableForm(form,disabled){$$('button[type="submit"]',form).forEach(b=>{b.disabled=disabled;b.textContent=disabled?'Submitting securely…':(form.id==='join-form'?'Submit membership application ↗':'Send preliminary request ↗')})}
async function submitJoin(form){if(!db)return;const raw=formData(form);if(raw.website_confirm)return;const ref=referenceCode('M');const fields={reference_code:ref,entity_name:raw.entity_name.trim(),founded_year:raw.founded_year?Number(raw.founded_year):null,website:raw.website||null,representative:raw.representative.trim(),representative_title:raw.representative_title.trim(),contact_email:raw.contact_email.trim(),region:raw.region||null,description:raw.description.trim(),charter_acknowledged:raw.charter_acknowledged==='on',authority_confirmed:raw.authority_confirmed==='on',privacy_acknowledged:raw.privacy_acknowledged==='on'};
 const msg=$('#join-message');disableForm(form,true);try{const {error}=await db.from('membership_applications').insert(fields);if(error)throw error;form.innerHTML=`<div class="success-box"><h3>Application transmitted</h3><p>The Registry database has received your application. Keep this reference for any future enquiry:</p><p style="font-weight:800;color:#143e2a;word-break:break-word">${safe(ref)}</p><p>This is a receipt, not a decision or confirmation of membership.</p><a href="#/membership" class="btn btn-ghost" style="margin-top:18px">About membership ↗</a></div>`}catch(e){console.error(e);msg.innerHTML=`<div class="error-box">Your application was not confirmed as received. Please try again. ${safe(e.message||'')}</div>`;disableForm(form,false)}}
async function submitCase(form){if(!db)return;const raw=formData(form);if(raw.website_confirm)return;const ref=referenceCode('C');const fields={reference_code:ref,title:raw.title.trim(),category:raw.category,requested_process:raw.requested_process,claimant:raw.claimant.trim(),respondent:raw.respondent.trim(),filer_name:raw.filer_name.trim(),filer_role:raw.filer_role.trim(),contact_email:raw.contact_email.trim(),consent_status:raw.consent_status,summary:raw.summary.trim(),relief_requested:raw.relief_requested.trim(),authority_confirmed:raw.authority_confirmed==='on',accept_limitations:raw.accept_limitations==='on',privacy_acknowledged:raw.privacy_acknowledged==='on'};
 const msg=$('#case-message');disableForm(form,true);try{const {error}=await db.from('case_submissions').insert(fields);if(error)throw error;form.innerHTML=`<div class="success-box"><h3>Preliminary request received</h3><p>Your private request has been recorded by the Registry database. Save your reference:</p><p style="font-weight:800;color:#143e2a;word-break:break-word">${safe(ref)}</p><p>Submission does not constitute acceptance of a case or confirmation of jurisdiction. The Registry must first verify authority and consent.</p><a href="#/cases" class="btn btn-ghost" style="margin-top:18px">Public case register ↗</a></div>`}catch(e){console.error(e);msg.innerHTML=`<div class="error-box">Your request was not confirmed as received. Please try again. ${safe(e.message||'')}</div>`;disableForm(form,false)}}
async function initAdmin(){if(!db)return;try{const {data:{user},error}=await db.auth.getUser();if(error||!user)return;const {data:role,error:roleError}=await db.from('admin_users').select('user_id').eq('user_id',user.id).maybeSingle();if(roleError||!role)return;await showAdminWorkspace()}catch(e){console.error(e)}}
async function showAdminWorkspace(){const root=$('#admin-root');if(!root)return;root.innerHTML=`<div class="admin-tools"><span class="eyebrow">Protected Registry workspace</span><button id="admin-logout" class="btn btn-ghost btn-small" type="button">Sign out</button></div><div class="admin-grid" id="admin-stats"><div class="admin-stat"><strong>—</strong><span>Pending applications</span></div><div class="admin-stat"><strong>—</strong><span>Case requests</span></div><div class="admin-stat"><strong>—</strong><span>Public cases</span></div></div><div class="tab-bar"><button class="tab ${adminTab==='cases'?'active':''}" data-admin-tab="cases">Case submissions</button><button class="tab ${adminTab==='members'?'active':''}" data-admin-tab="members">Membership applications</button><button class="tab ${adminTab==='publish'?'active':''}" data-admin-tab="publish">Publish a case</button><button class="tab ${adminTab==='directory'?'active':''}" data-admin-tab="directory">Member directory</button></div><div id="admin-content" style="padding:25px 0"></div>`;await loadAdminData()}
let adminCases=[];let adminMembers=[];let adminPublished=[];let adminDirectory=[];
async function loadAdminData(){const content=$('#admin-content');if(!content)return;try{const result=await Promise.all([db.from('case_submissions').select('*').order('created_at',{ascending:false}).limit(200),db.from('membership_applications').select('*').order('created_at',{ascending:false}).limit(200),db.from('published_cases').select('*').order('published_at',{ascending:false}).limit(200),db.from('members').select('*').order('name').limit(200)]);for(const r of result){if(r.error)throw r.error}adminCases=result[0].data||[];adminMembers=result[1].data||[];adminPublished=result[2].data||[];adminDirectory=result[3].data||[];$('#admin-stats').innerHTML=`<div class="admin-stat"><strong>${adminMembers.filter(x=>x.status==='received').length}</strong><span>New applications</span></div><div class="admin-stat"><strong>${adminCases.filter(x=>x.status==='received').length}</strong><span>New case requests</span></div><div class="admin-stat"><strong>${adminPublished.length}</strong><span>Public case records</span></div><div class="admin-stat"><strong>${adminDirectory.filter(x=>x.is_public&&x.status==='active').length}</strong><span>Public members</span></div>`;renderAdminTab()}catch(e){console.error(e);content.innerHTML=`<div class="error-box">Could not access the Registry. Your account may not have administrator privileges, or the database may be unavailable.</div>`}}
function renderAdminTab(){const content=$('#admin-content');if(!content)return;$$('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===adminTab));
 if(adminTab==='cases'){content.innerHTML=`<h3>Confidential case intake</h3><p>Only approved Registry administrators may read these records. Never publish the full private submission.</p><label class="admin-search-label" for="admin-case-search">Search submitted cases privately</label><input id="admin-case-search" type="search" data-admin-search class="admin-search" placeholder="Case reference, title, party or contact"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Reference / date</th><th>Parties and contact</th><th>Request</th><th>Status</th><th>Action</th></tr></thead><tbody>${adminCases.map(c=>`<tr><td>${safe(c.reference_code)}<br><small>${readDate(c.created_at)}</small></td><td>${safe(c.claimant)} v. ${safe(c.respondent)}<br><small>${safe(c.filer_name)} (${safe(c.contact_email)})</small></td><td class="td-long"><strong>${safe(c.title)}</strong><details><summary>Private details</summary><p>${safe(c.summary)}</p><p><strong>Requested:</strong> ${safe(c.relief_requested)}</p><p><strong>Consent:</strong> ${safe(c.consent_status)}</p></details></td><td>${safe(statusName(c.status))}</td><td><select data-admin-case-status="${safe(c.id)}" aria-label="Update status for ${safe(c.reference_code)}"><option value="received" ${c.status==='received'?'selected':''}>Received</option><option value="under_review" ${c.status==='under_review'?'selected':''}>Under review</option><option value="accepted" ${c.status==='accepted'?'selected':''}>Accepted</option><option value="closed" ${c.status==='closed'?'selected':''}>Closed</option><option value="rejected" ${c.status==='rejected'?'selected':''}>Declined</option></select></td></tr>`).join('')||'<tr><td colspan="5">No private case requests received.</td></tr>'}</tbody></table></div>`}
 else if(adminTab==='members'){content.innerHTML=`<h3>Private membership applications</h3><p>Applications do not confer membership automatically. Approve formal admission separately through the competent governing body. Only approved applicants may be separately published in the member directory.</p><label class="admin-search-label" for="admin-member-search">Search membership applications privately</label><input id="admin-member-search" type="search" data-admin-search class="admin-search" placeholder="Application reference, micronation or representative"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Reference</th><th>Micronation</th><th>Representative</th><th>Description</th><th>Status</th></tr></thead><tbody>${adminMembers.map(m=>`<tr><td>${safe(m.reference_code)}<br><small>${readDate(m.created_at)}</small></td><td>${safe(m.entity_name)}<br><small>${safe(m.website||'')}</small></td><td>${safe(m.representative)}<br><small>${safe(m.contact_email)}</small></td><td class="td-long">${safe(m.description)}</td><td><select data-admin-member-status="${safe(m.id)}" aria-label="Update status for ${safe(m.reference_code)}"><option value="received" ${m.status==='received'?'selected':''}>Received</option><option value="under_review" ${m.status==='under_review'?'selected':''}>Under review</option><option value="approved" ${m.status==='approved'?'selected':''}>Approved</option><option value="rejected" ${m.status==='rejected'?'selected':''}>Declined</option></select></td></tr>`).join('')||'<tr><td colspan="5">No membership applications received.</td></tr>'}</tbody></table></div>`}
 else if(adminTab==='directory'){
   const approved=adminMembers.filter(m=>m.status==='approved'&&!adminDirectory.some(d=>d.name.toLocaleLowerCase()===m.entity_name.toLocaleLowerCase()));
   content.innerHTML=`<h3>Public member directory</h3>
   <p>A reviewed and approved membership application is not public until the Registry has verified permission to list the micronation. This tool never publishes private contact details.</p>
   <div class="document-list">${adminDirectory.length?adminDirectory.map(m=>`<div class="document-row"><div><h3>${safe(m.name)}</h3><p>${m.is_public&&m.status==='active'?'Public listing':'Not publicly listed'} · ${readDate(m.admitted_on)}</p></div><button class="btn btn-ghost btn-small" data-member-publish-toggle="${safe(m.id)}" data-visible="${m.is_public&&m.status==='active'?'true':'false'}" type="button">${m.is_public&&m.status==='active'?'Unpublish':'Publish'} member</button></div>`).join(''):'<p>There are no member directory records.</p>'}</div>
   <h3 style="margin-top:30px">Publish an approved member</h3>
   <form id="publish-member-form" class="form-card" style="max-width:900px;box-shadow:none">
     <div class="field"><label for="approved-member-select">Approved membership application *</label><select id="approved-member-select" name="approved_application" required><option value="">Choose an approved application</option>${approved.map(m=>`<option value="${safe(m.id)}">${safe(m.entity_name)} — ${safe(m.reference_code)}</option>`).join('')}</select><small>First review the application in the Membership applications tab and record an approved institutional decision.</small></div>
     <div class="field"><label for="member-admission-date">Date of formal admission *</label><input id="member-admission-date" name="admitted_on" type="date" required value="${new Date().toISOString().slice(0,10)}"></div>
     <label class="check-field"><input name="publication_consent" type="checkbox" required> <span>I confirm formal admission was approved, and the representative has separately authorised public listing of the micronation's name, website and admission date.</span></label>
     <div id="publish-member-message" role="status"></div>
     <button type="submit" class="btn btn-primary" ${approved.length?'':'disabled'}>Publish approved member ↗</button>
   </form>`;
 }
 else{content.innerHTML=`<h3>Publish a public case record</h3><p>Only publish information permitted for disclosure. Never copy private filings wholesale. Check all parties' confidentiality rights and legal obligations first.</p><form id="publish-form" class="form-card" style="max-width:900px;box-shadow:none"><div class="field-row"><div class="field"><label>Case number *</label><input name="case_number" required maxlength="40" placeholder="PMAC 2026-01"></div><div class="field"><label>Status *</label><select name="status" required><option value="pending">Pending</option><option value="active">In progress</option><option value="closed">Closed</option></select></div></div><div class="field"><label>Case title *</label><input name="title" required maxlength="180"></div><div class="field-row"><div class="field"><label>Claimant (public label) *</label><input name="claimant" required maxlength="180"></div><div class="field"><label>Respondent (public label) *</label><input name="respondent" required maxlength="180"></div></div><div class="field"><label>Case category *</label><select name="category" required><option value="diplomatic">Diplomatic</option><option value="treaty">Treaty</option><option value="constitutional">Constitutional</option><option value="electoral">Electoral</option><option value="organisational">Organisational</option><option value="territorial">Territorial claims</option><option value="other">Other</option></select></div><div class="field"><label>Approved public summary</label><textarea name="summary" maxlength="2000"></textarea></div><label class="check-field"><input type="checkbox" name="publication_approved" required> <span>I confirm the Registry has authorised publication of this exact public summary, and necessary privacy and consent reviews are complete.</span></label><div id="publish-message"></div><button class="btn btn-primary" type="submit">Publish record ↗</button></form><h3 style="margin-top:35px">Published records (${adminPublished.length})</h3><div class="document-list">${adminPublished.map(c=>`<div class="document-row"><div><h3>${safe(c.case_number)} — ${safe(c.title)}</h3><p>${safe(statusName(c.status))} · ${readDate(c.published_at)}</p></div><button data-unpublish-id="${safe(c.id)}">Unpublish</button></div>`).join('')||'<p>No published cases.</p>'}</div>`}}
async function updateAdminStatus(table,id,value){const {error}=await db.from(table).update({status:value}).eq('id',id);if(error){toast(`Update failed: ${error.message}`);return}toast('Status updated');await loadAdminData()}
async function publishCase(form){const raw=formData(form);if(raw.publication_approved!=='on')return;const record={case_number:raw.case_number.trim(),title:raw.title.trim(),claimant:raw.claimant.trim(),respondent:raw.respondent.trim(),category:raw.category,status:raw.status,summary:raw.summary.trim(),is_public:true};const button=$('button[type="submit"]',form);button.disabled=true;try{const {error}=await db.from('published_cases').insert(record);if(error)throw error;toast('Public case record published');await loadAdminData()}catch(e){$('#publish-message').innerHTML=`<div class="error-box">${safe(e.message)}</div>`;button.disabled=false}}
async function publishMember(form){
 const raw=formData(form),msg=$('#publish-member-message');
 const app=adminMembers.find(m=>m.id===raw.approved_application&&m.status==='approved');
 if(!app||raw.publication_consent!=='on'){if(msg)msg.innerHTML='<div class="error-box">An approved application and explicit publication confirmation are required.</div>';return}
 if(adminDirectory.some(m=>m.name.toLocaleLowerCase()===app.entity_name.toLocaleLowerCase())){if(msg)msg.innerHTML='<div class="error-box">This member already has a directory record. Use the listing controls above.</div>';return}
 const button=$('button[type="submit"]',form);button.disabled=true;
 try{
   const {error}=await db.from('members').insert({name:app.entity_name,website:app.website||null,admitted_on:raw.admitted_on,status:'active',is_public:true});
   if(error)throw error;
   toast('Approved member published to directory');
   await loadAdminData();
 }catch(e){
   if(msg)msg.innerHTML='<div class="error-box">'+safe(e.message||'Could not publish member')+'</div>';
   button.disabled=false;
 }
}
async function togglePublicMember(id,visible){
 if(!confirm(visible?'Unpublish this member from the public directory?':'Publish this member? Confirm that membership and public listing permission remain valid.'))return;
 const member=adminDirectory.find(m=>m.id===id);if(!member)return;
 const changes=visible?{is_public:false}:{is_public:true,status:'active'};
 const {error}=await db.from('members').update(changes).eq('id',id);
 if(error){toast('Directory update failed: '+error.message);return}
 toast(visible?'Member removed from public directory':'Member published to public directory');
 await loadAdminData();
}
async function unpublishCase(id){if(!confirm('Remove this case from the public register?'))return;const {error}=await db.from('published_cases').update({is_public:false}).eq('id',id);if(error){toast(`Unpublish failed: ${error.message}`);return}toast('Public record unpublished');await loadAdminData()}
document.addEventListener('click',async e=>{const statusBtn=e.target.closest('[data-case-status]');if(statusBtn){activeCasesStatus=statusBtn.dataset.caseStatus;$$('[data-case-status]').forEach(b=>b.classList.toggle('active',b===statusBtn));renderPublicCases();return}const adminBtn=e.target.closest('[data-admin-tab]');if(adminBtn){adminTab=adminBtn.dataset.adminTab;renderAdminTab();return}if(e.target.closest('#admin-logout')){await db?.auth.signOut();toast('Signed out');await render();return}const unpub=e.target.closest('[data-unpublish-id]');if(unpub){await unpublishCase(unpub.dataset.unpublishId);return}const memberToggle=e.target.closest('[data-member-publish-toggle]');if(memberToggle){await togglePublicMember(memberToggle.dataset.memberPublishToggle,memberToggle.dataset.visible==='true')}});
document.addEventListener('input',e=>{if(e.target.id==='case-search'){activeCasesQuery=e.target.value;renderPublicCases()}else if(e.target.id==='member-search'){activeMembersQuery=e.target.value;renderMembers()}else if(e.target.matches('[data-admin-search]')){const query=e.target.value.toLocaleLowerCase().trim();const table=$('.admin-table', $('#admin-content'));if(table)$$('tbody tr',table).forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase().includes(query))}});
document.addEventListener('change',async e=>{if(e.target.id==='case-category'){renderPublicCases();return}if(e.target.matches('[data-admin-case-status]')){await updateAdminStatus('case_submissions',e.target.dataset.adminCaseStatus,e.target.value)}else if(e.target.matches('[data-admin-member-status]')){await updateAdminStatus('membership_applications',e.target.dataset.adminMemberStatus,e.target.value)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['join-form','case-form','admin-login','publish-form','publish-member-form'].includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;if(form.id==='join-form')await submitJoin(form);if(form.id==='case-form')await submitCase(form);if(form.id==='publish-form')await publishCase(form);if(form.id==='publish-member-form')await publishMember(form);if(form.id==='admin-login'){const raw=formData(form);const msg=$('#admin-login-message');const btn=$('button',form);btn.disabled=true;const {data,error}=await db.auth.signInWithPassword({email:raw.email,password:raw.password});if(error){msg.innerHTML=`<div class="error-box">${safe(error.message)}</div>`;btn.disabled=false;return}const {data:role}=await db.from('admin_users').select('user_id').eq('user_id',data.user.id).maybeSingle();if(!role){await db.auth.signOut();msg.innerHTML='<div class="error-box">This account has not been authorised for Registry access.</div>';btn.disabled=false;return}toast('Authorised Registry login');await showAdminWorkspace()}});
$('#menu-toggle').addEventListener('click',()=>{const nav=$('#mobile-nav');nav.hidden=!nav.hidden;$('#menu-toggle').setAttribute('aria-expanded',String(!nav.hidden))});
document.addEventListener('submit',e=>{
 if(!['home-search-form','nav-search-pane','member-search-form'].includes(e.target.id))return;
 e.preventDefault();
 const form=e.target;
 const data=new FormData(form);
 const q=String(data.get('q')||'').trim().slice(0,120);
 const target=form.id==='member-search-form'?'members':(data.get('target')||'cases');
 if(target==='members'){
   activeMembersQuery=q;
   if(route()==='/membership'){
     const inp=$('#member-search');if(inp)inp.value=q;
     renderMembers();
   }else window.location.hash='#/membership';
 }else{
   activeCasesQuery=q;
   if(route()==='/cases'){
     const inp=$('#case-search');if(inp)inp.value=q;
     renderPublicCases();
   }else window.location.hash='#/cases';
 }
 const pane=$('#nav-search-pane');if(pane)pane.hidden=true;
 const toggle=$('#nav-search-toggle');if(toggle)toggle.setAttribute('aria-expanded','false');
});
const navSearchToggle=$('#nav-search-toggle');
if(navSearchToggle) navSearchToggle.addEventListener('click',()=>{
  const pane=$('#nav-search-pane'); pane.hidden=!pane.hidden;
  navSearchToggle.setAttribute('aria-expanded',String(!pane.hidden));
  if(!pane.hidden) $('#nav-case-query')?.focus();
});
document.addEventListener('click',e=>{
 if(e.target.closest('#clear-case-search')){
   activeCasesQuery='';activeCasesStatus='all';
   const input=$('#case-search');if(input)input.value='';
   const cat=$('#case-category');if(cat)cat.value='all';
   $$('[data-case-status]').forEach(b=>b.classList.toggle('active',b.dataset.caseStatus==='all'));
   renderPublicCases();
 }
 if(e.target.closest('#clear-member-search')){
   activeMembersQuery='';const inp=$('#member-search');if(inp)inp.value='';renderMembers();
 }
});
document.addEventListener('change',e=>{
 if(e.target.id==='nav-search-type'){
   const inp=$('#nav-case-query');if(inp)inp.placeholder=e.target.value==='members'?'Micronation name or website':'Case number, party or keyword';
 }
});
window.addEventListener('hashchange',render);
$('#copyright-year').textContent=String(new Date().getFullYear());
render();
